Body:
Got it working. Looks like part of my error was setting proper context sizes for my model in OpenCode. Here's my schema for others.

```
{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "webui": {
      "npm": "@ai-sdk/openai-compatible",
      "options": {
        "baseURL": "https://***.***.com/api",
        "apiKey": "sk-***"
      },
      "models": {
        "gpt-oss-120b": {
          "id": "gpt-oss-120b",
          "name": "gpt-oss-120b",
          "reasoning": true,
          "options": { "reasoningEffort": "high" },
          "limit": { "context": 131072, "output": 32768 }
        },
        "gemma-4-31b": {
          "id": "gemma-4-31b",
          "name": "gemma-4-31b",
          "limit": { "context": 262144, "output": 16384 },
          "modalities": {
            "input": ["text", "image"],
            "output": ["text"]
          }
        },
        "qwen36-35b": {
          "id": "qwen36-35b",
          "name": "qwen36-35b",
          "limit": { "context": 262144, "output": 16384 }
        }
      }
    }
  }
}
```
